async function buildNextGoalAnalysis({ sendTelegramMessage = false } = {}) {
  const payload = await cachedProviderRequest("next-goal-live-fixtures", "/fixtures?live=all", 20000);
  const fixtures = (payload.response || []).map(normalizeProviderMatch)
    .filter(f => f.id && isFreshLiveFixture(f) && Number(f.minute || 0) >= 10 && Number(f.minute || 0) <= 95 && !isExcludedAnalysisCompetition(f));
  let bulkOdds = [];
  try { const bulk = await cachedProviderRequest("odds-live-all", "/odds/live", 10000); bulkOdds = bulk.response || []; }
  catch (e) { console.warn(`[Live odds bulk] ${e.message}`); }
  const results = [];
  let formEnrichedFixtures = 0;
  let statsFetchedFixtures = 0;
  for (const fixture of fixtures) {
    try {
      let oddsRow = bulkOdds.find(r => Number(r.fixture?.fixture?.id ?? r.fixture?.id ?? r.fixtureId ?? r.id) === fixture.id) || null;
      if (!oddsRow) {
        const oddsPayload = await cachedProviderRequest(`next-goal-live-odds:${fixture.id}`, `/odds/live?fixture=${fixture.id}`, 8000)
          .catch(e => { console.warn(`[LIVE ODDS ERROR] fixture=${fixture.id}: ${e.message}`); return { response: [] }; });
        oddsRow = (oddsPayload.response || []).find(r => Number(r.fixture?.fixture?.id ?? r.fixture?.id ?? r.fixtureId ?? r.id) === fixture.id) || null;
      }
      // Canlı oran/pazar bulunmayan maç için istatistik çağrısı yapma; gereksiz API yükünü azalt.
      let statsRows = [];
      if (oddsRow && oddsForFixture(oddsRow).length) {
        statsFetchedFixtures++;
        const statsPayload = await cachedProviderRequest(`next-goal-stats:${fixture.id}`, `/fixtures/statistics?fixture=${fixture.id}`, 12000)
          .catch(e => { console.warn(`[LIVE STATS ERROR] fixture=${fixture.id}: ${e.message}`); return { response: [] }; });
        statsRows = statsPayload.response || [];
      }
      let teamForms = null;
      const hasTeamGoalMarket = oddsRow && oddsForFixture(oddsRow).some(x => x.market.startsWith("EV ") || x.market.startsWith("DEP "));
      if (hasTeamGoalMarket && formEnrichedFixtures < 10 && fixture.homeId && fixture.awayId && fixture.leagueId && fixture.season) {
        formEnrichedFixtures++;
        const [homeForm, awayForm] = await Promise.all([
          fetchTeamRecentForm(fixture.homeId, fixture.id, fixture.leagueId, fixture.season, "home"),
          fetchTeamRecentForm(fixture.awayId, fixture.id, fixture.leagueId, fixture.season, "away")
        ]);
        teamForms = { home: homeForm, away: awayForm };
      }
      const analysis = await analyzeLiveFixture(fixture, oddsRow, statsRows, teamForms);
      results.push({ fixtureId: fixture.id, league: fixture.league, home: fixture.home, away: fixture.away,
        minute: fixture.minute, periodStatus: fixture.periodStatus, score: analysis.currentScore, prediction: "Canlı gol pazarları tarandı",
        confidence: (() => {
          const chosen = analysis.marketEvaluations?.find(x => x.market === analysis.mainPick);
          return (analysis.stats?.available && analysis.teamForm?.available && chosen?.edge >= 0.10 && chosen?.ev >= 0.10 && chosen?.modelProbability >= 0.70)
            ? "HIGH"
            : (analysis.stats?.available && chosen?.edge >= 0.06 && chosen?.ev >= 0.06 && chosen?.modelProbability >= 0.47)
              ? "MEDIUM" : "LOW";
        })(), valueScore: analysis.valueScore, edge: analysis.edge,
        status: analysis.mainPick ? "VALUE_CANDIDATE" : (!oddsRow ? "LIVE_ODDS_UNAVAILABLE" : (analysis.periodStatus === "HT" ? "HALFTIME_WAIT" : "NO_VALUE")),
        mainPick: analysis.mainPick, alternative: analysis.alternative, note: analysis.note,
        reasonCounts: analysis.reasonCounts,
        // Aynı taramada alınan canlı istatistik anlık görüntüsü; son kontrolde API
        // geçici olarak boş dönerse yalnızca bu tarama için yedek olarak kullanılır.
        statsSnapshot: statsRows,
        marketCoverage: analysis.marketEvaluations.map(x => x.market),
        bestRejectedMarket: analysis.marketEvaluations[0] ? { market: analysis.marketEvaluations[0].market, edge: Number((analysis.marketEvaluations[0].edge * 100).toFixed(1)), ev: Number((analysis.marketEvaluations[0].ev * 100).toFixed(1)) } : null,
        teamForm: analysis.teamForm,
        teamForms,
        valuePick: analysis.mainPick ? { outcome: analysis.mainPick, bookmaker: analysis.source || "Canlı oran kaynağı" } : null
      });
    } catch (error) {
      results.push({ fixtureId: fixture.id, league: fixture.league, home: fixture.home, away: fixture.away,
        minute: fixture.minute, periodStatus: fixture.periodStatus, score: `${fixture.homeScore}-${fixture.awayScore}`, prediction: "Analiz tamamlanamadı",
        confidence: "LOW", status: "PARTIAL_DATA", reason: error.message });
    }
  }
  const valueCandidates = results.filter(x => x.status === "VALUE_CANDIDATE")
    .sort((a,b) => Number(b.valueScore || 0) - Number(a.valueScore || 0));
  let top = null;
  let telegram = null;
  if (valueCandidates.length) {
    // İlk aday son kontrolde geçersizleşirse tüm taramayı boşa çıkarma:
    // sıradaki adayları da güncel fikstür + canlı oran + canlı istatistikle doğrula.
    // Son kontrolde pazar değişmişse eski pazara zorlamak yerine güncel en iyi pazarı kullan.
    let freshChecks = 0;
    let freshSkipped = 0;
    for (const candidate of valueCandidates) {
      freshChecks++;
      const fixtureId = Number(candidate.fixtureId);
      try {
        const freshPayload = await cachedProviderRequest(
          `final-live-fixture:${fixtureId}:${Date.now()}`,
          `/fixtures?id=${fixtureId}`, 0
        );
        const freshRow = (freshPayload.response || []).find(r =>
          Number(r.fixture?.id ?? r.fixture?.fixture?.id ?? r.fixtureId ?? r.id) === fixtureId
        ) || (freshPayload.response || [])[0];

        if (!freshRow) {
          freshSkipped++;
          console.log(`[AUTO LIVE SKIP] fixture=${fixtureId}: son doğrulamada fikstür bulunamadı; sıradaki adaya geçiliyor.`);
          continue;
        }

        const freshFixture = normalizeProviderMatch(freshRow);
        if (freshFixture.status !== "LIVE" ||
            ["HT", "FT", "AET", "PEN"].includes(freshFixture.periodStatus)) {
          freshSkipped++;
          console.log(`[AUTO LIVE SKIP] fixture=${fixtureId}: canlı değil/periyot uygun değil (${freshFixture.periodStatus}); sıradaki adaya geçiliyor.`);
          continue;
        }

        const [freshOddsPayload, freshStatsPayload] = await Promise.all([
          cachedProviderRequest(`final-live-odds:${fixtureId}:${Date.now()}`, `/odds/live?fixture=${fixtureId}`, 0)
            .catch(error => {
              console.warn(`[AUTO LIVE FINAL ODDS] fixture=${fixtureId}: ${error.message}`);
              return { response: [] };
            }),
          cachedProviderRequest(`final-live-stats:${fixtureId}:${Date.now()}`, `/fixtures/statistics?fixture=${fixtureId}`, 0)
            .catch(error => {
              console.warn(`[AUTO LIVE FINAL STATS] fixture=${fixtureId}: ${error.message}`);
              return { response: [] };
            })
        ]);

        let freshOdds = (freshOddsPayload.response || []).find(r =>
          Number(r.fixture?.fixture?.id ?? r.fixture?.id ?? r.fixtureId ?? r.id) === fixtureId
        ) || null;

        if (!freshOdds) {
          try {
            const freshBulk = await cachedProviderRequest(`final-live-odds-bulk:${Date.now()}`, "/odds/live", 0);
            freshOdds = (freshBulk.response || []).find(r =>
              Number(r.fixture?.fixture?.id ?? r.fixture?.id ?? r.fixtureId ?? r.id) === fixtureId
            ) || null;
          } catch (bulkError) {
            console.warn(`[AUTO LIVE FINAL ODDS BULK] ${bulkError.message}`);
          }
        }

        if (!freshOdds || !oddsForFixture(freshOdds).length) {
          freshSkipped++;
          console.log(`[AUTO LIVE SKIP] fixture=${fixtureId}: son kontrolde kullanılabilir canlı oran yok; sıradaki adaya geçiliyor.`);
          continue;
        }

        const freshStatsRows = Array.isArray(freshStatsPayload.response) && freshStatsPayload.response.length
          ? freshStatsPayload.response
          : (Array.isArray(candidate.statsSnapshot) ? candidate.statsSnapshot : []);
        const statsSource = freshStatsRows === candidate.statsSnapshot ? "same-scan-snapshot" : "fresh";
        const freshAnalysis = await analyzeLiveFixture(
          freshFixture, freshOdds, freshStatsRows, candidate.teamForms || null
        );

        if (!freshAnalysis.mainPick) {
          freshSkipped++;
          const bestEval = (freshAnalysis.marketEvaluations || [])[0] || null;
          console.log(`[AUTO LIVE SKIP] fixture=${fixtureId}: taze kontrolde değer şartı kalmadı; ` +
            `oldMarket=${candidate.mainPick || "none"} oldMinute=${candidate.minute} oldScore=${candidate.score} ` +
            `newMinute=${freshFixture.minute} newScore=${freshFixture.homeScore}-${freshFixture.awayScore} ` +
            `statsSource=${statsSource} markets=${(freshAnalysis.marketEvaluations || []).length} ` +
            `rejected=${JSON.stringify(freshAnalysis.reasonCounts || {})} ` +
            `best=${bestEval ? `${bestEval.market}|book=${bestEval.bookmaker}|odd=${bestEval.odd}|edge=${(bestEval.edge*100).toFixed(2)}%|ev=${(bestEval.ev*100).toFixed(2)}%` : "none"}; sıradaki adaya geçiliyor.`);
          continue;
        }

        const currentScore = freshAnalysis.currentScore ||
          `${freshFixture.homeScore}-${freshFixture.awayScore}`;
        const currentPick = freshAnalysis.mainPick;
        const key = `next-goal:${fixtureId}:${currentPick}`;

        if (sendTelegramMessage && autoSentFixtureKeys.has(key)) {
          freshSkipped++;
          console.log(`[AUTO LIVE SKIP] fixture=${fixtureId}: ${currentPick} daha önce gönderilmiş; sıradaki adaya geçiliyor.`);
          continue;
        }

        top = {
          ...candidate,
          minute: freshFixture.minute,
          score: currentScore,
          mainPick: currentPick,
          valueScore: freshAnalysis.valueScore,
          edge: freshAnalysis.edge,
          periodStatus: freshFixture.periodStatus,
          valuePick: {
            outcome: currentPick,
            bookmaker: freshAnalysis.source || "Canlı oran kaynağı"
          }
        };

        if (sendTelegramMessage) {
          try {
            const chosenEvaluation = freshAnalysis.marketEvaluations?.find(x => x.market === freshAnalysis.mainPick);
            const confidenceLabel = (
              chosenEvaluation?.edge >= 0.10 && chosenEvaluation?.ev >= 0.10 &&
              chosenEvaluation?.modelProbability >= 0.70 &&
              freshAnalysis.stats?.available && freshAnalysis.teamForm?.available
            ) ? "Yüksek" : (
              chosenEvaluation?.edge >= 0.06 && chosenEvaluation?.ev >= 0.06 &&
              chosenEvaluation?.modelProbability >= 0.47 && freshAnalysis.stats?.available
            ) ? "Orta" : "Düşük";
            telegram = await sendTelegram(
              `⚡ WINSCOPE CANLI TERCİH\n🏟️ ${top.home} VS ${top.away}\n⏱️ Dakika: ${top.minute}'\n⚽ Anlık skor: ${top.score}\n🎯 ANA TERCİH: ${top.mainPick}\n🛡️ Güven: ${confidenceLabel}\nWinScope · Canlı maç analizi`
            );
          } catch (sendError) {
            telegram = { sent: false, reason: sendError.message };
            console.error(`[AUTO LIVE TELEGRAM ERROR] fixture=${fixtureId}: ${sendError.message}`);
          }
        }

        if (telegram?.sent) {
          autoSentFixtureKeys.add(key);
          // Canlı tek tercih mesajı gönderilen maç, sonraki skor değişimleri için
          // gol taramasına da alınır. Başlangıç skoru mesaj anındaki gerçek skordur.
          const trackedScore = String(top.score || "0-0");
          goalTrackedFixtures.set(Number(top.fixtureId), {
            home: top.home, away: top.away, league: top.league,
            sourceLabel: "Canlı en güvenilir tek tercih",
            baselineScore: trackedScore
          });
          goalScoreCache.set(Number(top.fixtureId), trackedScore);
          console.log(`[GOOOOL TRACKING ADDED] fixture=${top.fixtureId} score=${trackedScore}`);
          if (databasePool) {
            try {
              await archiveDatabaseReady;
              await databasePool.query(`INSERT INTO winscope_live_predictions
                (fixture_id,home_team,away_team,market,signal_key,league,match_date,start_score,minute)
                VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)
                ON CONFLICT (fixture_id,market) DO NOTHING`,
                [top.fixtureId,top.home,top.away,top.mainPick,key,top.league,turkeyDateString(),top.score,top.minute]);
            } catch (dbError) {
              console.error(`[LIVE TRACKING SAVE ERROR] ${dbError.message}`);
            }
          }
        }
        // Bir aday taze kontrolden geçtiyse ve Telegram denemesi yapıldıysa
        // aynı taramada ikinci bir canlı bahis bildirimi gönderme.
        break;
      } catch (freshError) {
        freshSkipped++;
        console.error(`[AUTO LIVE FINAL CHECK ERROR] fixture=${fixtureId}: ${freshError.message}; sıradaki adaya geçiliyor.`);
      }
    }
    console.log(`[AUTO LIVE FINAL CHECK] candidates=${valueCandidates.length} checked=${freshChecks} skipped=${freshSkipped} selected=${top?.fixtureId || "none"} selectedMarket=${top?.mainPick || "none"} telegramSent=${Boolean(telegram?.sent)}`);
  }
  const reasonSummary = results.reduce((acc, x) => {
    acc[x.status] = (acc[x.status] || 0) + 1;
    for (const [reason, count] of Object.entries(x.reasonCounts || {})) {
      if (typeof count === "number" && count > 0) acc[`detail_${reason}`] = (acc[`detail_${reason}`] || 0) + count;
    }
    return acc;
  }, {});
  console.log(`[LIVE SCAN SUMMARY] liveFixtures=${fixtures.length} scanned=${results.length} oddsBulk=${bulkOdds.length} statsFetched=${statsFetchedFixtures} formEnriched=${formEnrichedFixtures} candidates=${valueCandidates.length} reasons=${JSON.stringify(reasonSummary)}`);
  return { status: "READY", type: "live", scanned: results.length, valueCandidates: valueCandidates.length,
    message: telegram?.sent ? "Canlı aday taze fikstür, oran ve değer kontrolünden geçti; Telegram bildirimi gönderildi." : (top ? "Canlı aday bulundu ve taze kontrolden geçti; Telegram gönderimi tamamlanmadı." : "Canlı maçlar tarandı; taze oran ve değer kontrolünü geçen gönderilebilir tercih bulunmadı."),
    reasonSummary, matches: results, topPick: top, picks: top ? [{ fixtureId: top.fixtureId, league: top.league, home: top.home, away: top.away, minute: top.minute, currentScore: top.score, market: top.mainPick, source: top.valuePick?.bookmaker, oddsBasis: "Gerçek canlı oran" }] : [], telegram };
}

