app.post("/api/analyses/approve", async (req, res) => {
  const body = req.body || {};
  if (!body.fixtureId || !body.home || !body.away) return res.status(400).json({ success: false, error: "Maç bilgileri eksik." });
  const approved = {
    fixture_id: Number(body.fixtureId), home_team: String(body.home), away_team: String(body.away),
    analysis: body.analysis || {}, created_at: new Date().toISOString()
  };
  archives.analyses.unshift(approved);
  archives.analyses = archives.analyses.slice(0, 100);
  const storage = await saveArchiveItem("analysis", approved);
  const parseScore = value => {
    const match = String(value || "").match(/(\d+)\s*[-:]\s*(\d+)/);
    return match ? `${Number(match[1])}-${Number(match[2])}` : null;
  };
  const tracking = {
    fixtureId:Number(body.fixtureId), home:String(body.home), away:String(body.away),
    predictedHT:parseScore(approved.analysis.halfTimeScore),
    predictedFT:parseScore(approved.analysis.fullTimeScore),
    alternativeFT:parseScore(approved.analysis.alternativeFullTimeScore),
    actualHT:null, actualFT:null, exactFT:null, exactHT:null,
    matchDate:String(body.matchDate || ""), settled:false, createdAt:new Date().toISOString()
  };
  const existing = predictionTracking.findIndex(x => x.fixtureId === tracking.fixtureId);
  if (existing >= 0) predictionTracking[existing] = tracking; else predictionTracking.unshift(tracking);
  let trackingPersisted = false;
  if (databasePool) {
    try {
      await archiveDatabaseReady;
      await databasePool.query(`INSERT INTO winscope_predictions(fixture_id,home_team,away_team,predicted_ht,predicted_ft,alternative_ft,match_date)
        VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(fixture_id) DO UPDATE SET home_team=EXCLUDED.home_team,away_team=EXCLUDED.away_team,
        predicted_ht=EXCLUDED.predicted_ht,predicted_ft=EXCLUDED.predicted_ft,alternative_ft=EXCLUDED.alternative_ft,match_date=EXCLUDED.match_date,
        actual_ht=NULL,actual_ft=NULL,exact_ft=NULL,exact_ht=NULL,settled_at=NULL`,
        [tracking.fixtureId,tracking.home,tracking.away,tracking.predictedHT,tracking.predictedFT,tracking.alternativeFT,tracking.matchDate]);
      trackingPersisted = true;
    } catch (error) { console.error(`[Prediction tracking] ${error.message}`); }
  }
  res.json({ success: true, persisted: storage.persisted, trackingPersisted, storageReason: storage.reason || storage.error || null });
});

app.get("/api/predictions/summary", async (_req, res) => {
  await archiveDatabaseReady;
  const rows = predictionTracking;
  const settled = rows.filter(x => x.settled && x.actualFT);
  const exactFT = settled.filter(x => x.exactFT === true).length;
  const exactHTRows = settled.filter(x => x.exactHT !== null);
  res.json({ total:rows.length, settled:settled.length, pending:rows.length-settled.length,
    exactFullTime:exactFT, exactFullTimeRate:settled.length?Math.round(100*exactFT/settled.length):null,
    exactHalfTime:exactHTRows.filter(x=>x.exactHT===true).length,
    exactHalfTimeRate:exactHTRows.length?Math.round(100*exactHTRows.filter(x=>x.exactHT===true).length/exactHTRows.length):null,
    results:settled.slice(0,100), note:"Yalnızca kullanıcı tarafından onaylanıp takip kaydına alınan analizler ölçülür." });
});

// Canlı tercih takip paneli: yalnızca Telegram'a gerçekten gönderilen canlı seçimleri sayar.
app.get("/api/live-predictions/summary", async (req, res) => {
  await archiveDatabaseReady;
  const period = req.query.period === "all" ? "all" : "week";
  let rows = [];
  let storageError = null;
  if (databasePool) {
    try {
      const result = period === "week"
        ? await databasePool.query(`SELECT fixture_id,home_team,away_team,market,league,match_date,start_score,minute,actual_score,outcome,settled_at,created_at
            FROM winscope_live_predictions WHERE created_at >= NOW() - INTERVAL '7 days' ORDER BY created_at DESC LIMIT 500`)
        : await databasePool.query(`SELECT fixture_id,home_team,away_team,market,league,match_date,start_score,minute,actual_score,outcome,settled_at,created_at
            FROM winscope_live_predictions ORDER BY created_at DESC LIMIT 500`);
      rows = result.rows.map(row => ({
        fixtureId:Number(row.fixture_id), home:row.home_team, away:row.away_team, market:row.market, league:row.league,
        matchDate:row.match_date, startScore:row.start_score, minute:row.minute, actualScore:row.actual_score,
        outcome:row.outcome, settled:Boolean(row.settled_at), createdAt:row.created_at
      }));
    } catch (error) {
      storageError = error.message;
      console.error(`[Live tracking summary] PostgreSQL okunamadı: ${error.message}`);
      rows = livePredictionTracking.filter(x => period === "all" || Date.now() - new Date(x.createdAt || 0).getTime() <= 7 * 86400000);
    }
  } else {
    rows = livePredictionTracking.filter(x => period === "all" || Date.now() - new Date(x.createdAt || 0).getTime() <= 7 * 86400000);
  }
  const settled = rows.filter(x => x.settled && (x.outcome === "won" || x.outcome === "lost"));
  const won = settled.filter(x => x.outcome === "won").length;
  const lost = settled.filter(x => x.outcome === "lost").length;
  res.json({
    period, total: rows.length, pending: rows.filter(x => !x.settled).length, won, lost,
    winRate: settled.length ? Math.round(100 * won / settled.length) : null,
    lossRate: settled.length ? Math.round(100 * lost / settled.length) : null,
    results: rows.slice(0, 50),
    persistentStorage: Boolean(databasePool), storageError,
    note: "Canlı tercih kayıtları PostgreSQL'den okunur; varsayılan dönem son 7 gündür. Yalnızca desteklenen pazarlar sonuçlandırılır."
  });
});

app.get("/api/coupon-tracking/summary", async (req, res) => {
  await archiveDatabaseReady;
  // Takip ekranı açıldığında bekleyen eski maçları da hemen sonuçlandırmayı dene.
  try { await settleCouponPredictions(); } catch (error) { console.warn(`[Coupon tracking refresh] ${error.message}`); }
  const period = req.query.period === "all" ? "all" : "week";
  let rows = [];
  let storageError = null;
  if (databasePool) {
    try {
      const result = period === "all"
        ? await databasePool.query(`SELECT coupon_key,coupon_type,fixture_id,home_team,away_team,league,market,start_score,actual_score,outcome,match_date,created_at,settled_at
            FROM winscope_coupon_predictions ORDER BY created_at DESC LIMIT 2000`)
        : await databasePool.query(`SELECT coupon_key,coupon_type,fixture_id,home_team,away_team,league,market,start_score,actual_score,outcome,match_date,created_at,settled_at
            FROM winscope_coupon_predictions WHERE created_at >= NOW() - INTERVAL '7 days' ORDER BY created_at DESC LIMIT 2000`);
      rows = result.rows.map(row => ({
        couponKey: row.coupon_key, couponType: row.coupon_type, fixtureId: Number(row.fixture_id),
        home: row.home_team, away: row.away_team, league: row.league, market: row.market,
        startScore: row.start_score, actualScore: row.actual_score, outcome: row.outcome,
        matchDate: row.match_date, settled: Boolean(row.settled_at), createdAt: row.created_at
      }));
    } catch (error) {
      storageError = error.message;
      console.error(`[Coupon tracking summary] PostgreSQL okunamadı: ${error.message}`);
    }
  }

  // Kupon sonuçları tek tek maç tercihlerinden değil, coupon_key gruplarından hesaplanır.
  const couponMap = new Map();
  for (const row of rows) {
    const key = String(row.couponKey || `${row.couponType}:${row.matchDate || ""}:${row.createdAt || ""}`);
    if (!couponMap.has(key)) couponMap.set(key, {
      couponKey: key, couponType: row.couponType, matchDate: row.matchDate,
      createdAt: row.createdAt, legs: []
    });
    couponMap.get(key).legs.push(row);
  }
  const couponsRaw = [...couponMap.values()].map(coupon => {
    const legs = coupon.legs;
    const lost = legs.some(x => x.settled && x.outcome === "lost");
    const won = legs.length > 0 && legs.every(x => x.settled && x.outcome === "won");
    const outcome = lost ? "lost" : won ? "won" : null;
    return {
      ...coupon, legCount: legs.length, settled: Boolean(outcome), outcome,
      pendingLegs: legs.filter(x => !x.settled).length,
      actualScore: legs.map(x => `${x.home} ${x.actualScore || "Bekliyor"} ${x.away}`).join(" · ")
    };
  }).sort((a,b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
  const uniqueCoupons = new Map();
  for (const coupon of couponsRaw) {
    const signature = `${coupon.couponType}|${String(coupon.matchDate || '').slice(0,10)}|${coupon.legs.map(x => `${x.fixtureId}:${String(x.market).trim().toLocaleLowerCase('tr-TR')}`).sort().join(',')}`;
    if (!uniqueCoupons.has(signature)) uniqueCoupons.set(signature, { ...coupon, duplicateCount: 1 });
    else uniqueCoupons.get(signature).duplicateCount++;
  }
  const coupons = [...uniqueCoupons.values()];

  const settled = coupons.filter(x => x.settled);
  const won = settled.filter(x => x.outcome === "won").length;
  const lost = settled.filter(x => x.outcome === "lost").length;
  const byTypeMap = new Map();
  for (const coupon of settled) {
    const key = coupon.couponType || "prematch";
    const item = byTypeMap.get(key) || { couponType: key, won: 0, lost: 0 };
    item[coupon.outcome]++;
    byTypeMap.set(key, item);
  }
  const byCouponType = [...byTypeMap.values()].map(x => ({
    ...x, winRate: x.won + x.lost ? Math.round(100*x.won/(x.won+x.lost)) : 0
  }));
  res.json({
    period, total: coupons.length, settled: settled.length,
    pending: coupons.filter(x => !x.settled).length, won, lost,
    winRate: settled.length ? Math.round(100*won/settled.length) : null,
    byCouponType, results: coupons.slice(0,100), persistentStorage: Boolean(databasePool), storageError,
    note: "Kupon başarı oranı kupon bazında hesaplanır; tüm ayaklar kazanırsa kupon kazanır, bir ayak kaybederse kupon kaybeder."
  });
});

// Günün Analizleri: üst düzey kulüp ligleri + A milli takım resmi turnuvaları/özel maçları; oran ve denge koşulları uygulanır.
// API-Football lig ID'leri: Premier League, La Liga, Bundesliga, Serie A, Ligue 1, Süper Lig.
// Günün analiz havuzu: büyük Avrupa ligleri + seçilmiş üst seviye ulusal ligler.
// Genç/reserve organizasyonları isim kontrolüyle her durumda dışarıda tutulur.
const DAILY_MAJOR_LEAGUE_IDS = new Set([
  2, 3, 848,                         // UEFA Champions / Europa / Conference League
  39, 40, 140, 78, 135, 61, 203,     // Big 5 + Championship + Süper Lig
  88, 94, 144, 179, 207, 218, 119,   // Netherlands, Portugal, Belgium, Scotland, Switzerland, Austria, Denmark
  197, 106, 128, 71, 253, 307,       // Greece, Poland, Argentina, Brazil, MLS, Saudi Pro League
  98, 292, 262                       // Japan, Korea, Mexico
]);
const DAILY_MAJOR_LEAGUE_NAMES = new Set([
  "premier league", "championship", "la liga", "bundesliga", "serie a", "ligue 1",
  "super lig", "süper lig", "eredivisie", "primeira liga", "jupiler pro league",
  "pro league", "scottish premiership", "super league", "bundesliga austria",
  "superliga", "super league 1", "ekstraklasa", "liga profesional argentina",
  "brasileirão série a", "serie a", "major league soccer", "mls", "saudi pro league",
  "j1 league", "k league 1", "liga mx", "uefa champions league", "uefa europa league",
  "uefa conference league",
  "uefa nations league", "nations league",
  "fifa world cup qualification", "world cup qualification", "world cup qualifiers",
  "africa cup of nations qualification", "africa cup of nations qualifiers", "afcon qualifiers",
  "concacaf nations league", "concacaf gold cup",
  "afc asian cup qualification", "asian cup qualifiers",
  "international friendlies", "international friendly", "friendlies",
  "men friendlies", "world friendlies"
]);
function isDailyMajorLeague(match) {
  // Büyük lig öncelik etiketi artık eleme filtresi değildir.
  return !isExcludedAnalysisCompetition(match);
}
function dailyAnalysisLeaguePriority(match) {
  const name=String(match.league||"").toLocaleLowerCase("en");
  const id=Number(match.leagueId);
  if (DAILY_MAJOR_LEAGUE_IDS.has(id) || DAILY_MAJOR_LEAGUE_NAMES.has(name)) return 1;
  if (/\\b(nations league|world cup|africa cup|asian cup|gold cup|international friendly|friendlies|qualif)/i.test(name)) return 2;
  return 3;
}
const DAILY_MARKET_ODDS_MIN = 1.50;
const DAILY_MARKET_ODDS_MAX = 1.73;
function dailyMarketCandidate(oddsRow) {
  const rows = oddsForFixture(oddsRow);
  const valid = rows.filter(x => ["KG VAR", "MS 2.5 ÜST"].includes(x.market) &&
    Number.isFinite(Number(x.odd)) && Number(x.odd) >= DAILY_MARKET_ODDS_MIN && Number(x.odd) <= DAILY_MARKET_ODDS_MAX);
  if (!valid.length) return null;
  // Aynı markette birden fazla kaynak varsa 1.615'e en yakın gerçek fiyatı seç.
  valid.sort((a,b) => Math.abs(Number(a.odd)-1.615) - Math.abs(Number(b.odd)-1.615));
  return valid[0];
}
function dailyOpponentBalance(oddsRow) {
  const rows = oddsForFixture(oddsRow).filter(x => x.market === "MS 1" &&
    Number.isFinite(Number(x.homeOdd)) && Number.isFinite(Number(x.drawOdd)) && Number.isFinite(Number(x.awayOdd)));
  for (const row of rows) {
    const inv = [1/Number(row.homeOdd), 1/Number(row.drawOdd), 1/Number(row.awayOdd)];
    const sum = inv.reduce((a,b)=>a+b,0);
    const probs = inv.map(x=>x/sum);
    const sorted = [...probs].sort((a,b)=>b-a);
    // Aşırı favori ve çok zayıf rakip elemesi: favori olasılığı <= %65,
    // rakip olasılığı >= %15 ve iki takım galibiyet olasılık farkı <= %45 puan.
    const maxTeam = Math.max(probs[0], probs[2]);
    const minTeam = Math.min(probs[0], probs[2]);
    if (maxTeam <= 0.65 && minTeam >= 0.15 && Math.abs(probs[0]-probs[2]) <= 0.45)
      return { balanced:true, bookmaker:row.bookmaker, homeProbability:Math.round(probs[0]*100), awayProbability:Math.round(probs[2]*100) };
  }
  return { balanced:false };
}
async function persistDailyAnalysisRun(job) {
  dailyAnalysisRunCache.set(job.date, job);
  if (!databasePool) return { persisted:false, reason:"DATABASE_URL tanımlı değil" };
  try {
    await archiveDatabaseReady;
    await databasePool.query(`INSERT INTO winscope_daily_analysis_runs(match_date,status,result,error,started_at,finished_at,updated_at)
      VALUES($1,$2,$3::jsonb,$4,$5,$6,NOW())
      ON CONFLICT(match_date) DO UPDATE SET status=EXCLUDED.status,result=EXCLUDED.result,error=EXCLUDED.error,
      started_at=EXCLUDED.started_at,finished_at=EXCLUDED.finished_at,updated_at=NOW()`,
      [job.date,job.status,job.result ? JSON.stringify(job.result) : null,job.error || null,job.startedAt || null,job.finishedAt || null]);
    return { persisted:true };
  } catch (error) {
    console.error(`[Daily analysis] Günlük çalışma kaydı yazılamadı: ${error.message}`);
    return { persisted:false, error:error.message };
  }
}
const DAILY_ANALYSIS_STALE_MS = 20 * 60 * 1000;
const dailyAnalysisStartLocks = new Set();
async function findDailyAnalysisRun(date) {
  let active = dailyAnalysisJobs.get(date);
  if (active && ["queued","running"].includes(active.status)) {
    const started = Date.parse(active.updatedAt || active.startedAt || "");
    if (Number.isFinite(started) && Date.now() - started > DAILY_ANALYSIS_STALE_MS) {
      active.status = "failed";
      active.error = `Analiz ${Math.round((Date.now()-started)/60000)} dakikadır ilerlemedi; takılı iş olarak işaretlendi.`;
      active.finishedAt = new Date().toISOString();
      console.error(`[Daily analysis watchdog] ${date}: ${active.error} current=${active.current||0}/${active.total||0} match=${active.currentMatch||"-"}`);
      await persistDailyAnalysisRun(active);
    } else return active;
  }
  if (databasePool) {
    try {
      await archiveDatabaseReady;
      const q = await databasePool.query("SELECT match_date::text,status,result,error,started_at,finished_at,updated_at FROM winscope_daily_analysis_runs WHERE match_date=$1::date", [date]);
      if (q.rows[0]) {
        const r=q.rows[0];
        const job={date,status:r.status,result:r.result||null,error:r.error||null,startedAt:r.started_at,finishedAt:r.finished_at,updatedAt:r.updated_at};
        const started = Date.parse(job.updatedAt || job.startedAt || "");
        if (["queued","running"].includes(job.status) && Number.isFinite(started) && Date.now()-started>DAILY_ANALYSIS_STALE_MS) {
          job.status="failed";
          job.error=`Veritabanındaki analiz ${Math.round((Date.now()-started)/60000)} dakikadır ilerlemedi; yeniden başlatılabilir.`;
          job.finishedAt=new Date().toISOString();
          await persistDailyAnalysisRun(job);
          console.error(`[Daily analysis watchdog] ${date}: veritabanındaki takılı iş başarısız olarak işaretlendi.`);
        }
        dailyAnalysisRunCache.set(date,job);
        dailyAnalysisJobs.set(date,job);
        return job;
      }
    } catch (error) { console.warn(`[Daily analysis] Günlük kayıt okunamadı: ${error.message}`); }
  }
  return dailyAnalysisRunCache.get(date) || null;
}
async function startDailyAnalysisIfNeeded(date, { force=false } = {}) {
  if (dailyAnalysisStartLocks.has(date)) return await findDailyAnalysisRun(date) || {date,status:"running"};
  dailyAnalysisStartLocks.add(date);
  try {
    const existing = await findDailyAnalysisRun(date);
    if (existing && !force && ["queued","running","completed"].includes(existing.status)) return existing;
    const job = { date, status:"queued", current:0, total:0, selected:0, currentMatch:"", startedAt:new Date().toISOString(), updatedAt:new Date().toISOString() };
    dailyAnalysisJobs.set(date, job);
    await persistDailyAnalysisRun(job);
    setImmediate(() => runDailyAnalysisJob(job));
    return job;
  } finally { dailyAnalysisStartLocks.delete(date); }
}
async function runDailyAnalysisJob(job) {
  const { date } = job;
  try {
    job.status = "running";
    await persistDailyAnalysisRun(job);
    const payload = await cachedProviderRequest(`fixtures:${date}`, `/fixtures?date=${date}&timezone=Europe/Istanbul`, 60000);
    const scheduledFixtures = (payload.response || []).map(normalizeProviderMatch).filter(m => String(m.status || "").toUpperCase() === "NS");
    const fixtures = scheduledFixtures.filter(isDailyMajorLeague)
      .sort((a,b) => dailyAnalysisLeaguePriority(a)-dailyAnalysisLeaguePriority(b));
    const leagueCounts = {};
    const priorityCounts = { major:0, international:0, other:0 };
    for (const m of fixtures) {
      const p=dailyAnalysisLeaguePriority(m);
      priorityCounts[p===1?"major":p===2?"international":"other"]++;
    }
    job.priorityCounts=priorityCounts;
    for (const m of scheduledFixtures) leagueCounts[m.league] = (leagueCounts[m.league] || 0) + 1;
    job.fixtureFeedCount = (payload.response || []).length;
    job.scheduledCount = scheduledFixtures.length;
    job.majorLeagueCount = fixtures.length;
    job.leagueBreakdown = Object.entries(leagueCounts).sort((a,b)=>b[1]-a[1]).slice(0,30);
    job.total = fixtures.length;
    job.majorLeagueCount = fixtures.length;
    job.excludedOtherLeagues = scheduledFixtures.length - fixtures.length;
    // Tanı amaçlı: hangi organizasyonların kadın/U filtresine takıldığını açıkça göster.
    const excludedLeagueCounts = {};
    for (const m of scheduledFixtures.filter(isExcludedAnalysisCompetition)) {
      const key = `${m.country || "Ülke bilinmiyor"} · ${m.league || "Lig bilinmiyor"}`;
      excludedLeagueCounts[key] = (excludedLeagueCounts[key] || 0) + 1;
    }
    job.excludedLeagueBreakdown = Object.entries(excludedLeagueCounts)
      .sort((a,b) => b[1]-a[1]).slice(0,30);
    const selected = [], rejected = { noOdds:0, outsideRange:0, unbalanced:0, noForm:0, noSupportedPick:0 };
    for (let i=0; i<fixtures.length; i++) {
      const match = fixtures[i];
      job.current = i + 1;
      job.currentMatch = `${match.home} - ${match.away}`;
      job.updatedAt = new Date().toISOString();
      if (i === 0 || (i + 1) % 5 === 0 || i + 1 === fixtures.length) {
        await persistDailyAnalysisRun(job);
        console.log(`[Daily analysis progress] ${date}: ${job.current}/${job.total} · ${job.currentMatch} · seçilen=${job.selected||0}`);
      }
      try {
        const oddsRow = await getOddsForFixture(match.id, date).catch(()=>null);
        if (!oddsRow) { rejected.noOdds++; continue; }
        const market = dailyMarketCandidate(oddsRow);
        if (!market) { rejected.outsideRange++; continue; }
        const balance = dailyOpponentBalance(oddsRow);
        if (!balance.balanced) { rejected.unbalanced++; continue; }
        const [homeForm, awayForm] = await Promise.all([
          fetchTeamRecentForm(match.homeId, match.id, match.leagueId, match.season, "home"),
          fetchTeamRecentForm(match.awayId, match.id, match.leagueId, match.season, "away")
        ]);
        if (!homeForm?.available || !awayForm?.available) { rejected.noForm++; continue; }
        const prematchFixture = { ...match, status:"NS", minute:null, homeScore:0, awayScore:0, htHomeScore:null, htAwayScore:null };
        let scores = scorePrediction(prematchFixture, homeForm, awayForm, null, oddsRow);
        const forms = { home:homeForm, away:awayForm };
        const supported = chooseSupportedMarket(oddsRow, "prematch", prematchFixture, forms, null, oddsRow);
        const mainPick = supported && ["KG VAR","MS 2.5 ÜST"].includes(supported.market) &&
          Number(supported.odd) >= DAILY_MARKET_ODDS_MIN && Number(supported.odd) <= DAILY_MARKET_ODDS_MAX
          ? supported.market : market.market;
        // Ana tercih belirlendikten sonra tam skor aynı pazar koşulu altında seçilir.
        scores = scorePrediction(prematchFixture, homeForm, awayForm, null, oddsRow, mainPick);
        console.log(`[Daily score] fixture=${match.id} ${match.home} vs ${match.away} | bookmaker=${scores.oddsBookmaker||"n/a"} | 1X2=${JSON.stringify(scores.market1x2)} | xG=${JSON.stringify(scores.expectedGoals)} | HT-xG=${JSON.stringify(scores.expectedHalfTimeGoals)} | unconditional=${JSON.stringify(scores.topScoreCandidates)} | marketScenario=${JSON.stringify(scores.marketScenarioCandidates)} | model=${scores.modelVersion} fit=${scores.modelFitError} markets=${JSON.stringify(scores.marketTargetsUsed)} | pick=${mainPick} | HT=${scores.halfTimeScore} FT=${scores.fullTimeScore} | basis=${scores.scoreBasis} | HTbasis=${scores.halfTimeBasis}`);
        const other = mainPick === "KG VAR" ? "MS 2.5 ÜST" : "KG VAR";
        const altRow = oddsForFixture(oddsRow).find(x=>x.market===other && Number(x.odd)>=DAILY_MARKET_ODDS_MIN && Number(x.odd)<=DAILY_MARKET_ODDS_MAX);
        const analysis = {
          fixtureId:match.id, matchDate:date, home:match.home, away:match.away, league:match.league,
          halfTimeScore:scores.halfTimeScore, fullTimeScore:scores.fullTimeScore,
          alternativeFullTimeScore:scores.alternativeFullTimeScore || null,
          mainPick, alternative:altRow ? other : "Aralıkta doğrulanmış alternatif yok",
          selectionScore: supported && Number.isFinite(Number(supported.selectionScore)) ? Number(supported.selectionScore) : null,
          marketProbability: supported && Number.isFinite(Number(supported.marketProbability)) ? Number(supported.marketProbability) : null,
          formSupport: supported?.teamFormAvailable === true ? 1 : 0,
          selectionBookmaker: supported?.bookmaker || null,
          surprise:scores.surprise || null,
          scoreBasis:scores.scoreBasis || "Maç önü oranları ve erişilebilen son 5 maç formu",
          expectedGoals:scores.expectedGoals || null,
          expectedHalfTimeGoals:scores.expectedHalfTimeGoals || null,
          halfTimeBasis:scores.halfTimeBasis || null,
          topScoreCandidates:scores.topScoreCandidates || [],
          marketScenarioCandidates:scores.marketScenarioCandidates || [],
          marketScenarioScore:scores.marketScenarioScore || null,
          marketScenarioAlternativeScore:scores.marketScenarioAlternativeScore || null,
          scoreProbability:scores.scoreProbability ?? null,
          alternativeScoreProbability:scores.alternativeScoreProbability ?? null,
          marketScenarioProbability:scores.marketScenarioProbability ?? null,
          scoreProbabilityType:scores.scoreProbabilityType || "UNCONDITIONAL",
          scoreCondition:scores.scoreCondition || mainPick,
          scoreModelVersion:scores.modelVersion || "V5_1X2_PRIORITY_2D",
          scoreModelFitError:scores.modelFitError ?? null,
          oddsBookmaker:scores.oddsBookmaker || supported?.bookmaker || null,
          market1x2:scores.market1x2 || null,
          scoreMarketsUsed:scores.marketTargetsUsed || [],
          selectionBasis:"KG VAR / MS 2.5 ÜST 1.50–1.73 ve dengeli rakip oranları",
          created_at:new Date().toISOString()
        };
        selected.push(analysis);
        console.log(`[Daily analysis saved] fixture=${match.id} ${match.home} vs ${match.away} | pick=${analysis.mainPick} | HT=${analysis.halfTimeScore} | FT=${analysis.fullTimeScore} | xG=${JSON.stringify(analysis.expectedGoals)} | HT-xG=${JSON.stringify(analysis.expectedHalfTimeGoals)} | candidates=${JSON.stringify(analysis.topScoreCandidates)} | 1X2=${JSON.stringify(analysis.market1x2)} | book=${analysis.oddsBookmaker||"n/a"}`);
        const trackedMarkets = [analysis.mainPick, analysis.alternative]
          .filter(m => ["KG VAR", "KG YOK", "MS 2.5 ÜST", "EV 1.5 ÜST", "DEP 1.5 ÜST"].includes(String(m || "").trim()));
        for (const trackedMarket of [...new Set(trackedMarkets)]) {
          const tracked = { fixtureId:match.id, matchDate:date, home:match.home, away:match.away, league:match.league, market:trackedMarket, actualScore:null, outcome:null, settled:false, createdAt:analysis.created_at };
          const at = dailyMarketTracking.findIndex(x => x.fixtureId === tracked.fixtureId && x.market === tracked.market);
          if (at >= 0) dailyMarketTracking[at] = tracked; else dailyMarketTracking.unshift(tracked);
          if (databasePool) {
            await databasePool.query(`INSERT INTO winscope_daily_market_predictions
              (fixture_id,match_date,home_team,away_team,league,market)
              VALUES($1,$2,$3,$4,$5,$6)
              ON CONFLICT(fixture_id,market) DO UPDATE SET match_date=EXCLUDED.match_date,
              home_team=EXCLUDED.home_team,away_team=EXCLUDED.away_team,league=EXCLUDED.league`,
              [tracked.fixtureId,tracked.matchDate,tracked.home,tracked.away,tracked.league,tracked.market]);
          }
        }
        const archiveRow = { fixture_id:match.id, home_team:match.home, away_team:match.away, match_date:date, analysis, created_at:analysis.created_at };
        archives.analyses = [archiveRow, ...archives.analyses.filter(x=>Number(x.fixture_id ?? x.fixtureId)!==Number(match.id))].slice(0,100);
        await saveArchiveItem("analysis", archiveRow);
        job.selected = selected.length;
      } catch (err) { console.warn(`[Daily analysis] fixture=${match.id}: ${err.message}`); rejected.noSupportedPick++; }
    }
    await settleDailyMarketPredictions();
    job.result = { success:true, date, fixtureFeedCount:job.fixtureFeedCount || 0,
      scheduledCount:job.scheduledCount || 0, fixtures:fixtures.length, majorLeagueFixtures:fixtures.length,
      leagueBreakdown:job.leagueBreakdown || [], excludedLeagueBreakdown:job.excludedLeagueBreakdown || [],
      excludedOtherLeagues:job.excludedOtherLeagues || 0, selected:selected.length, rejected,
      filters:{ leagues:["Premier League", "La Liga", "Bundesliga", "Serie A", "Ligue 1", "Süper Lig"], oddsMin:DAILY_MARKET_ODDS_MIN, oddsMax:DAILY_MARKET_ODDS_MAX, balancedOpponents:true },
      persistentStorage:Boolean(databasePool) };
    job.status = "completed";
    await persistDailyAnalysisRun(job);
  } catch (error) {
    job.status = "failed";
    job.error = error.message;
    console.error(`[Daily analysis job] ${date}: ${error.message}`);
  } finally {
    job.finishedAt = new Date().toISOString();
    await persistDailyAnalysisRun(job);
  }
}
