// Takip edilen canlı maçların skorunu 45 saniyede bir kontrol et.
// Canlı listede görünmeyen fixture'lar ayrıca ID ile sorgulanır; sessizce atlanmaz.
setInterval(async () => {
  if (goalScanInFlight || goalTrackedFixtures.size === 0) return;
  goalScanInFlight = true;
  const trackedCount = goalTrackedFixtures.size;
  let matchedCount = 0;
  let changedCount = 0;
  try {
    const payload = await cachedProviderRequest("liveList:goal-alert", "/fixtures?live=all", 20_000);
    const liveMatches = (payload.response || []).map(normalizeProviderMatch);
    const liveById = new Map(liveMatches.map(m => [Number(m.id), m]));

    for (const [fixtureId, tracked] of goalTrackedFixtures.entries()) {
      let match = liveById.get(fixtureId);

      // API'nin genel canlı listesinden düşen takipli maçı fixture ID ile tekrar kontrol et.
      if (!match) {
        try {
          const direct = await cachedProviderRequest(
            `goal-alert-fixture:${fixtureId}`,
            `/fixtures?id=${encodeURIComponent(fixtureId)}`,
            10_000
          );
          const row = direct.response?.[0];
          if (row) match = normalizeProviderMatch(row);
        } catch (lookupError) {
          console.warn(`[GOOOOL FIXTURE LOOKUP ERROR] ${fixtureId}: ${lookupError.message}`);
          continue;
        }
      }

      if (!match) {
        console.warn(`[GOOOOL TRACKING MISS] fixture=${fixtureId}; canlı liste ve ID sorgusunda bulunamadı.`);
        continue;
      }
      matchedCount++;

      const score = `${match.homeScore}-${match.awayScore}`;
      const previous = goalScoreCache.get(fixtureId) ?? tracked.baselineScore ?? score;
      if (score !== previous) {
        changedCount++;
        const message = `⚽ WINSCOPE GOOOOOL!\n🏆 ${match.league || tracked.league || "Lig"}\n⚽ ${match.home || tracked.home} - ${match.away || tracked.away}\n📣 Skor değişti: ${previous} → ${score}\n⏱️ Dakika: ${match.minute ?? "?"}'\n🎯 Takip nedeni: ${tracked.sourceLabel || "Canlı maç takibi"}`;
        try {
          const sent = await sendTelegram(message);
          if (sent.sent) {
            goalScoreCache.set(fixtureId, score);
            tracked.baselineScore = score;
            console.log(`[GOOOOL Alert OK] ${fixtureId} ${previous} -> ${score}`);
          } else {
            console.error(`[GOOOOL Alert NOT SENT] ${fixtureId}: ${sent.reason || "Telegram gönderimi başarısız"}`);
          }
        } catch (error) {
          console.error(`[GOOOOL Alert Error] ${fixtureId}: ${error.message}`);
        }
      }

      if (["FT", "AET", "PEN", "CANC", "ABD", "AWD", "WO"].includes(String(match.periodStatus || match.status || "").toUpperCase())) {
        goalTrackedFixtures.delete(fixtureId);
        goalScoreCache.delete(fixtureId);
        console.log(`[GOOOOL TRACKING CLOSED] fixture=${fixtureId} finalScore=${score}`);
      }
    }
    console.log(`[GOOOOL SCAN] tracked=${trackedCount} matched=${matchedCount} scoreChanges=${changedCount}`);
  } catch (error) {
    console.error(`[GOOOOL Scan Error] ${error.message}`);
  } finally {
    goalScanInFlight = false;
  }
}, 45_000);

let couponSettlementInFlight = false;
async function settleCouponPredictions() {
  if (!databasePool || couponSettlementInFlight) return;
  couponSettlementInFlight = true;
  try {
    // Kontrol edilen ama henüz bitmemiş maçlar 10 dakika sonra tekrar denenir.
    // Böylece ilk 40 eski/kayıp fixture kaydı kuyruğu sonsuza kadar bloke etmez.
    const pending = await databasePool.query(`SELECT tracking_id,fixture_id,market,coupon_type,home_team,away_team,league,telegram_notified_at
      FROM winscope_coupon_predictions
      WHERE settled_at IS NULL
        AND (settlement_checked_at IS NULL OR settlement_checked_at < NOW() - INTERVAL '10 minutes')
        AND ((match_date ~ '^\\d{4}-\\d{2}-\\d{2}$' AND match_date::date <= (NOW() AT TIME ZONE 'Europe/Istanbul')::date)
             OR (match_date IS NULL AND created_at < NOW() - INTERVAL '3 hours'))
      ORDER BY COALESCE(match_date,'') ASC, created_at ASC LIMIT 60`);
    if (!pending.rows.length) return;
    const fixtureGroups = new Map();
    for (const item of pending.rows) {
      const id = Number(item.fixture_id);
      if (!fixtureGroups.has(id)) fixtureGroups.set(id, []);
      fixtureGroups.get(id).push(item);
    }
    for (const [fixtureId, items] of fixtureGroups) {
      try {
        const payload = await cachedProviderRequest(`coupon-settle:${fixtureId}`, `/fixtures?id=${fixtureId}`, 5 * 60 * 1000);
        await databasePool.query(
          `UPDATE winscope_coupon_predictions SET settlement_checked_at=NOW()
           WHERE tracking_id = ANY($1::bigint[]) AND settled_at IS NULL`,
          [items.map(x => x.tracking_id)]
        );
        const row = payload.response?.[0];
        const status = String(row?.fixture?.status?.short || '').toUpperCase();
        if (!row || !['FT','AET','PEN'].includes(status) || row.goals?.home == null || row.goals?.away == null) continue;
        const homeGoals = Number(row.goals.home), awayGoals = Number(row.goals.away);
        const htHome = row.score?.halftime?.home == null ? null : Number(row.score.halftime.home);
        const htAway = row.score?.halftime?.away == null ? null : Number(row.score.halftime.away);
        const actualScore = `${homeGoals}-${awayGoals}`;
        for (const item of items) {
          const result = evaluateTrackedLiveMarket(item.market, homeGoals, awayGoals, htHome, htAway);
          if (result == null) {
            console.warn(`[Coupon tracking] Desteklenmeyen pazar: fixture=${fixtureId} market=${item.market}`);
            continue;
          }
          const outcome = result ? 'won' : 'lost';
          const updated = await databasePool.query(
            `UPDATE winscope_coupon_predictions SET actual_score=$2,outcome=$3,settled_at=NOW()
             WHERE tracking_id=$1 AND settled_at IS NULL RETURNING tracking_id`,
            [item.tracking_id, actualScore, outcome]
          );
          if (!updated.rowCount || outcome !== 'won' || item.telegram_notified_at) continue;
          const marketKey = String(item.market || '').trim().toLocaleLowerCase('tr-TR');
          // Aynı fixture+market birden fazla kupon/tekrar kayıt içinde bulunsa da tek bildirim.
          const claim = await databasePool.query(
            `INSERT INTO winscope_coupon_result_notifications(fixture_id,market_key,status)
             VALUES($1,$2,'sending') ON CONFLICT(fixture_id,market_key) DO NOTHING RETURNING fixture_id`,
            [fixtureId, marketKey]
          );
          if (!claim.rowCount) {
            await databasePool.query(
              'UPDATE winscope_coupon_predictions SET telegram_notified_at=COALESCE(telegram_notified_at,NOW()) WHERE tracking_id=$1',
              [item.tracking_id]
            );
            continue;
          }
          const message = [
            '🏆 WINSCOPE KUPON TERCİHİ KAZANDI!',
            `🏟️ ${item.league || 'Lig bilgisi yok'}`,
            `⚽ ${item.home_team} - ${item.away_team}`,
            `🎯 Kazanan tercih: ${item.market}`,
            `📊 Maç sonucu: ${actualScore}`,
            `📌 Kupon türü: ${item.coupon_type === 'live' ? 'Canlı' : item.coupon_type === 'surprise' ? 'Sürpriz' : 'Maç önü'}`
          ].join('\n');
          try {
            const sent = await sendTelegram(message);
            if (sent.sent) {
              await databasePool.query(
                `UPDATE winscope_coupon_result_notifications SET status='sent',telegram_message_id=$3,sent_at=NOW()
                 WHERE fixture_id=$1 AND market_key=$2`, [fixtureId, marketKey, sent.messageId]
              );
              await databasePool.query(
                'UPDATE winscope_coupon_predictions SET telegram_notified_at=NOW() WHERE tracking_id=$1 AND telegram_notified_at IS NULL',
                [item.tracking_id]
              );
            } else {
              await databasePool.query("DELETE FROM winscope_coupon_result_notifications WHERE fixture_id=$1 AND market_key=$2 AND status='sending'", [fixtureId, marketKey]);
            }
          } catch (telegramError) {
            await databasePool.query("DELETE FROM winscope_coupon_result_notifications WHERE fixture_id=$1 AND market_key=$2 AND status='sending'", [fixtureId, marketKey]);
            console.warn(`[Coupon tracking Telegram] fixture=${fixtureId} market=${marketKey}: ${telegramError.message}`);
          }
        }
      } catch (error) {
        console.warn(`[Coupon tracking settlement] fixture=${fixtureId}: ${error.message}`);
      }
    }
  } finally {
    couponSettlementInFlight = false;
  }
}
setTimeout(() => { void settleCouponPredictions(); }, 30_000);
setInterval(() => { void settleCouponPredictions(); }, 5 * 60 * 1000);

function evaluateTrackedLiveMarket(market, homeGoals, awayGoals, halfHome, halfAway) {
  const m = String(market || "").toLocaleUpperCase("tr-TR").replace(/İ/g, "I").replace(/Ü/g, "U").replace(/Ş/g, "S").replace(/Ğ/g, "G").replace(/Ç/g, "C").replace(/Ö/g, "O");
  if (m.includes("KG VAR")) return homeGoals > 0 && awayGoals > 0;
  if (m.includes("KG YOK")) return homeGoals === 0 || awayGoals === 0;
  const homeLine = m.match(/(?:EV|EV SAHIBI)\s*(\d+(?:[.,]\d+)?)\s*(UST|ALT)/);
  if (homeLine) return homeLine[2] === "UST" ? homeGoals > Number(homeLine[1].replace(",", ".")) : homeGoals < Number(homeLine[1].replace(",", "."));
  const awayLine = m.match(/(?:DEP|DEPLASMAN)\s*(\d+(?:[.,]\d+)?)\s*(UST|ALT)/);
  if (awayLine) return awayLine[2] === "UST" ? awayGoals > Number(awayLine[1].replace(",", ".")) : awayGoals < Number(awayLine[1].replace(",", "."));
  const ht = m.includes("IY ") || m.includes("ILK YARI") || m.includes("HALF");
  const h = ht ? halfHome : homeGoals, a = ht ? halfAway : awayGoals;
  if (ht && (h == null || a == null)) return null;
  const over = m.match(/(?:MS |IY |ILK YARI )?(\d+(?:[.,]\d+)?)\s*UST/);
  const under = m.match(/(?:MS |IY |ILK YARI )?(\d+(?:[.,]\d+)?)\s*ALT/);
  if (over) return h + a > Number(over[1].replace(",", "."));
  if (under) return h + a < Number(under[1].replace(",", "."));
  return null;
}
async function settleLivePredictions() {
  const pending = livePredictionTracking.filter(x => !x.settled).slice(0, 30);
  for (const item of pending) {
    try {
      const payload = await cachedProviderRequest(`live-settle:${item.fixtureId}`, `/fixtures?id=${item.fixtureId}`, 5 * 60 * 1000);
      const row = payload.response?.[0];
      const status = String(row?.fixture?.status?.short || "").toUpperCase();
      if (!row || !["FT","AET","PEN"].includes(status) || row.goals?.home == null || row.goals?.away == null) continue;
      const homeGoals = Number(row.goals.home), awayGoals = Number(row.goals.away);
      const htHome = row.score?.halftime?.home == null ? null : Number(row.score.halftime.home);
      const htAway = row.score?.halftime?.away == null ? null : Number(row.score.halftime.away);
      const result = evaluateTrackedLiveMarket(item.market, homeGoals, awayGoals, htHome, htAway);
      if (result == null) {
        console.warn(`[Live tracking] Desteklenmeyen pazar sonuçlandırılmadı fixture=${item.fixtureId} market=${item.market}`);
        continue;
      }
      item.actualScore = `${homeGoals}-${awayGoals}`;
      item.outcome = result ? "won" : "lost";
      item.settled = true;
      item.settledAt = new Date().toISOString();
      if (databasePool) {
        await databasePool.query(
          "UPDATE winscope_live_predictions SET actual_score=$3,outcome=$4,settled_at=NOW() WHERE fixture_id=$1 AND market=$2",
          [item.fixtureId,item.market,item.actualScore,item.outcome]
        );
      }
    } catch (error) { console.warn(`[Live prediction settlement] fixture=${item.fixtureId}: ${error.message}`); }
  }
}
async function settleDailyMarketPredictions() {
  if (!databasePool) return;
  try {
    const pending = await databasePool.query(`SELECT fixture_id,match_date,home_team,away_team,league,market
      FROM winscope_daily_market_predictions
      WHERE settled_at IS NULL
        AND match_date ~ '^\\d{4}-\\d{2}-\\d{2}$'
        AND match_date::date <= (NOW() AT TIME ZONE 'Europe/Istanbul')::date
      ORDER BY match_date ASC LIMIT 250`);
    const groups = new Map();
    for (const item of pending.rows) {
      const id = Number(item.fixture_id);
      if (!groups.has(id)) groups.set(id, []);
      groups.get(id).push(item);
    }
    for (const [fixtureId, items] of groups) {
      try {
        const payload = await cachedProviderRequest(`daily-market-settle:${fixtureId}`, `/fixtures?id=${fixtureId}`, 5 * 60 * 1000);
        const row = payload.response?.[0];
        const status = String(row?.fixture?.status?.short || '').toUpperCase();
        if (!row || !['FT','AET','PEN'].includes(status) || row.goals?.home == null || row.goals?.away == null) continue;
        const homeGoals = Number(row.goals.home), awayGoals = Number(row.goals.away);
        const actualScore = `${homeGoals}-${awayGoals}`;
        for (const item of items) {
          const won = evaluateTrackedLiveMarket(item.market, homeGoals, awayGoals,
            row.score?.halftime?.home == null ? null : Number(row.score.halftime.home),
            row.score?.halftime?.away == null ? null : Number(row.score.halftime.away));
          if (won == null) continue;
          await databasePool.query(`UPDATE winscope_daily_market_predictions
            SET actual_score=$2,outcome=$3,settled_at=NOW()
            WHERE fixture_id=$1 AND market=$4 AND settled_at IS NULL`,
            [fixtureId, actualScore, won ? 'won' : 'lost', item.market]);
        }
      } catch (error) { console.warn(`[Daily market settlement] fixture=${fixtureId}: ${error.message}`); }
    }
  } catch (error) { console.error(`[Daily market settlement] ${error.message}`); }
}

async function backfillDailyMarketPredictions(matchDate) {
  if (!databasePool || !/^\d{4}-\d{2}-\d{2}$/.test(String(matchDate || ""))) return { inserted:0, scanned:0 };
  await archiveDatabaseReady;
  const archived = await databasePool.query(`
    SELECT payload FROM winscope_archive
    WHERE category='analysis'
      AND COALESCE(payload->>'match_date', payload->'analysis'->>'matchDate')=$1
    ORDER BY id ASC
  `, [matchDate]);
  let inserted=0, scanned=0;
  const allowed = new Set(["KG VAR","KG YOK","MS 2.5 ÜST","EV 1.5 ÜST","DEP 1.5 ÜST"]);
  for (const record of archived.rows) {
    const payload = record.payload || {};
    const a = payload.analysis || payload;
    const fixtureId = Number(payload.fixture_id || payload.fixtureId || a.fixtureId);
    const home = String(payload.home_team || a.home || "");
    const away = String(payload.away_team || a.away || "");
    const league = String(a.league || payload.league || "");
    if (!fixtureId || !home || !away) continue;
    scanned++;
    const markets = [...new Set([a.mainPick, a.alternative].map(x=>String(x || "").trim()).filter(x=>allowed.has(x)))];
    for (const market of markets) {
      const result = await databasePool.query(`
        INSERT INTO winscope_daily_market_predictions
          (fixture_id,match_date,home_team,away_team,league,market)
        VALUES($1,$2,$3,$4,$5,$6)
        ON CONFLICT(fixture_id,market) DO NOTHING
      `, [fixtureId, matchDate, home, away, league, market]);
      inserted += result.rowCount || 0;
    }
  }
  if (inserted) console.log(`[Daily market backfill] ${matchDate}: arşiv=${scanned}, yeni takip=${inserted}`);
  return { inserted, scanned };
}

app.get("/api/daily-market-tracking/summary", async (req, res) => {
  const date = String(req.query.date || "").trim();
  try {
    if (databasePool) {
      await archiveDatabaseReady;
      if (date) {
        await backfillDailyMarketPredictions(date);
        await settleDailyMarketPredictions();
      }
      const params = date ? [date] : [];
      const where = date ? "WHERE match_date=$1" : "";
      const result = await databasePool.query(`SELECT market,
        COUNT(*)::int AS total,
        COUNT(*) FILTER (WHERE outcome='won')::int AS won,
        COUNT(*) FILTER (WHERE outcome='lost')::int AS lost,
        COUNT(*) FILTER (WHERE settled_at IS NULL)::int AS pending
        FROM winscope_daily_market_predictions ${where}
        GROUP BY market ORDER BY market`, params);
      return res.json({ success:true, date:date || null, markets:result.rows });
    }
    const rows = dailyMarketTracking.filter(x => !date || x.matchDate === date);
    const markets = [...new Set(rows.map(x=>x.market))].map(m => {
      const subset=rows.filter(x=>x.market===m);
      return { market:m,total:subset.length,won:subset.filter(x=>x.outcome==='won').length,
        lost:subset.filter(x=>x.outcome==='lost').length,pending:subset.filter(x=>!x.settled).length };
    });
    res.json({ success:true,date:date||null,markets });
  } catch (error) { res.status(500).json({success:false,error:error.message,markets:[]}); }
});

async function settleApprovedPredictions() {
  if (!predictionTracking.some(x => !x.settled)) return;
  for (const item of predictionTracking.filter(x => !x.settled).slice(0, 20)) {
    try {
      const payload = await cachedProviderRequest(`settle-fixture:${item.fixtureId}`, `/fixtures?id=${item.fixtureId}`, 5 * 60 * 1000);
      const row = payload.response?.[0];
      const status = String(row?.fixture?.status?.short || "").toUpperCase();
      if (!row || !["FT","AET","PEN"].includes(status) || row.goals?.home == null || row.goals?.away == null) continue;
      const actualFT = `${Number(row.goals.home)}-${Number(row.goals.away)}`;
      const ht = row.score?.halftime;
      const actualHT = ht?.home == null || ht?.away == null ? null : `${Number(ht.home)}-${Number(ht.away)}`;
      item.actualFT = actualFT; item.actualHT = actualHT;
      item.exactFT = item.predictedFT ? item.predictedFT === actualFT : null;
      item.exactHT = item.predictedHT && actualHT ? item.predictedHT === actualHT : null;
      item.settled = true; item.settledAt = new Date().toISOString();
      if (databasePool) await databasePool.query(`UPDATE winscope_predictions SET actual_ht=$2,actual_ft=$3,exact_ft=$4,exact_ht=$5,settled_at=NOW() WHERE fixture_id=$1`,
        [item.fixtureId,actualHT,actualFT,item.exactFT,item.exactHT]);
    } catch (error) { console.warn(`[Prediction settlement] fixture=${item.fixtureId}: ${error.message}`); }
  }
}
setInterval(() => { void settleApprovedPredictions(); }, 15 * 60 * 1000);
setInterval(() => { void settleLivePredictions(); }, 15 * 60 * 1000);
setInterval(() => { void settleDailyMarketPredictions(); }, 15 * 60 * 1000);

setTimeout(() => { void settleDailyMarketPredictions(); }, 60000);
